// ─── File: ConfirmCommitDemo.java ───
// Runnable demo: confirm ONLY after durable commit; 202+PENDING for long work.
package com.bank.confirmcommit;

import java.math.BigDecimal;
import java.util.concurrent.*;
import java.util.logging.*;

public class ConfirmCommitDemo {

    private static final Logger log = Logger.getLogger("ConfirmCommit");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        log.setUseParentHandlers(false);
        log.addHandler(handler);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws Exception {
        StatusStore store = new StatusStore();
        PaymentService service = new PaymentService(store);

        // 1) Fast payment that COMMITS → UI may show CONFIRMED (honest).
        String r1 = service.payAndConfirm("PAY-1", "SAV2001",
                new BigDecimal("50000"), true);
        log.info(() -> "Fast payment PAY-1 UI message = " + r1);

        // 2) Fast payment whose commit FAILS/rolls back → must NOT say confirmed.
        String r2 = service.payAndConfirm("PAY-2", "SAV2001",
                new BigDecimal("50000"), false);
        log.info(() -> "Fast payment PAY-2 UI message = " + r2);

        // 3) Long-running payment → 202 PENDING now, CONFIRMED later on real outcome.
        String accepted = service.submitLongRunning("PAY-3", "SAV2001",
                new BigDecimal("75000"));
        log.info(() -> "Long payment PAY-3 immediate UI = " + accepted);

        // Client polls the status until it reflects the committed outcome.
        ScheduledExecutorService sched = Executors.newSingleThreadScheduledExecutor();
        for (int i = 1; i <= 4; i++) {
            sched.schedule(() -> log.info(() -> "Poll PAY-3 status = "
                    + store.status("PAY-3")), i * 250L, TimeUnit.MILLISECONDS);
        }
        sched.schedule(sched::shutdown, 1200, TimeUnit.MILLISECONDS);
        sched.awaitTermination(2, TimeUnit.SECONDS);
    }
}

// ─── model/Payment.java ───
class Payment {
    enum Status { PENDING, CONFIRMED, FAILED }
}

// ─── store/StatusStore.java (durable status, source of the UI truth) ───
class StatusStore {
    private final ConcurrentHashMap<String, Payment.Status> statuses =
            new ConcurrentHashMap<>();
    void set(String paymentId, Payment.Status s) { statuses.put(paymentId, s); }
    // Idempotent transition: never flip a terminal FAILED to CONFIRMED.
    void confirmFromCommittedOutcome(String paymentId, boolean committed) {
        statuses.compute(paymentId, (k, cur) -> {
            if (cur == Payment.Status.FAILED) return Payment.Status.FAILED;
            return committed ? Payment.Status.CONFIRMED : Payment.Status.FAILED;
        });
    }
    Payment.Status status(String paymentId) { return statuses.get(paymentId); }
}

// ─── service/PaymentService.java ───
class PaymentService {
    private static final Logger log = Logger.getLogger("ConfirmCommit");
    private final StatusStore store;
    private final ScheduledExecutorService workers =
            Executors.newScheduledThreadPool(2);
    PaymentService(StatusStore store) { this.store = store; }

    // Fast path: perform the charge, attempt commit, confirm ONLY if committed.
    String payAndConfirm(String id, String account, BigDecimal amount,
                         boolean commitSucceeds) {
        store.set(id, Payment.Status.PENDING);
        boolean committed = attemptDurableCommit(id, commitSucceeds);
        store.confirmFromCommittedOutcome(id, committed);
        return committed
                ? "CONFIRMED (money durably recorded)"
                : "FAILED — please retry (nothing was charged)";
    }

    // Long-running path: 202 PENDING now; transition later on the real outcome.
    String submitLongRunning(String id, String account, BigDecimal amount) {
        store.set(id, Payment.Status.PENDING);
        // Background: do slow SWIFT work, then confirm from the committed outcome.
        workers.schedule(() -> {
            boolean committed = attemptDurableCommit(id, true); // succeeds here
            store.confirmFromCommittedOutcome(id, committed);
            log.info(() -> "PAY-3 background committed=" + committed
                    + " → status " + store.status(id));
        }, 700, TimeUnit.MILLISECONDS);
        return "202 Accepted — status PENDING, poll /payments/" + id + "/status";
    }

    // Simulates the durable DB commit which can succeed or roll back.
    private boolean attemptDurableCommit(String id, boolean succeed) {
        if (!succeed) {
            log.warning("Commit for " + id + " rolled back (fraud/insufficient funds)");
            return false;
        }
        log.info(() -> "Commit for " + id + " durable OK");
        return true;
    }
}

class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
